#!/usr/bin/env bash
# 療育カリキュラム作成システム v2.2 単一ファイル導入インストーラー
# 配布用コードのみが含まれ、実利用者データ、APIキー、パスワードは含まれません。
# コードを確認のうえ実行してください。既存サービスと競合した場合は中止します。
set -Eeuo pipefail
umask 077

EXPECTED_SHA256="0634d97e2e43199bc115e0ffef9b58c04e3c9a18db5c8b017438bed020cc8bb0"
BUNDLE_NAME="ryoiku_deploy_kit_v2_2.zip"

usage() {
cat <<'HELP'
使い方:
  bash install-ryoiku-v2.2.sh --verify         # 内蔵ZIPの整合性を確認（sudo不要）
  bash install-ryoiku-v2.2.sh --extract DIR    # 導入キットをDIRへ展開（sudo不要）
  sudo bash install-ryoiku-v2.2.sh             # 新規インストール

必要: Ubuntu Server / Docker / Docker Compose / curl / unzip / python3 / ss
新規導入専用です。既存の /opt/ryoiku-curriculum は上書きしません。
インストーラーは受信ポートを開放せず、コンテナを127.0.0.1:8080にのみ公開します。
HELP
}

