__RYOIKU_EMBEDDED_BASE64__
  local actual
  actual="$(sha256sum "$archive" | awk '{print $1}')"
  if [[ "$actual" != "$EXPECTED_SHA256" ]]; then
    printf 'エラー: 配布データのSHA256が一致しません。実行を中止します。\n' >&2
    exit 1
  fi
  if ! unzip -tqq "$archive"; then
    printf 'エラー: 内蔵ZIPのファイル構造を確認できません。\n' >&2
    exit 1
  fi
}

case "${1:---install}" in
  --help|-h) usage; exit 0 ;;
  --verify|--extract|--install) MODE="${1}" ;;
  *) usage >&2; exit 2 ;;
esac
for cmd in base64 sha256sum awk mktemp unzip; do
  if ! command -v "$cmd" >/dev/null 2>&1; then
    printf '必要なコマンドがありません: %s\n' "$cmd" >&2; exit 1
  fi
done

TMP_DIR="$(mktemp -d)"
cleanup() { rm -rf "$TMP_DIR"; }
trap cleanup EXIT
unpack_archive "$TMP_DIR/$BUNDLE_NAME"

if [[ "$MODE" == --verify ]]; then
  printf 'OK: 内蔵ZIPの検証に成功しました (SHA256 %s)\n' "$EXPECTED_SHA256"
  exit 0
fi

if [[ "$MODE" == --extract ]]; then
  if [[ -z "${2:-}" ]]; then echo '展開先のディレクトリを指定してください' >&2; exit 2; fi
  mkdir -p "$2"
  unzip -q "$TMP_DIR/$BUNDLE_NAME" -d "$2"
  printf '展開しました: %s/ryoiku_deploy_kit_v2_2\n' "$2"
  exit 0
fi

if [[ "$EUID" -ne 0 ]]; then
  echo '新規インストールには sudo が必要です: sudo bash install-ryoiku-v2.2.sh' >&2
  exit 1
fi
unzip -q "$TMP_DIR/$BUNDLE_NAME" -d "$TMP_DIR"
SETUP="$TMP_DIR/ryoiku_deploy_kit_v2_2/setup.sh"
if [[ ! -f "$SETUP" ]]; then
  echo 'エラー: 内蔵キットにsetup.shがありません' >&2
  exit 1
fi
printf '内蔵ファイル検証済み。既存サービスは変更せずに競合チェックして導入します。\n'
# stdinを保持して管理者ID/パスワード、Tailscale設定の選択を対話入力可能にする。
bash "$SETUP"
